                warnings.push(
                  `**${label}**: \`${legacy}\` was modified but \`${session}\` was not.`,
                );
              } else if (!legacyChanged && sessionChanged) {
                warnings.push(
                  `**${label}**: \`${session}\` was modified but \`${legacy}\` was not.`,
                );
              }
            }

            const MARKER = '<!-- agent-session-drift-check -->';

